// Production catalogue and checkout. Static prototype data is never loaded here.
const events=[];
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=paise=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:paise%100?2:0}).format((paise||0)/100);
const dateParts=event=>({date:new Intl.DateTimeFormat('en-IN',{timeZone:event.timezone,weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date(event.starts_at)),time:new Intl.DateTimeFormat('en-IN',{timeZone:event.timezone,hour:'numeric',minute:'2-digit'}).format(new Date(event.starts_at)),month:new Intl.DateTimeFormat('en-IN',{timeZone:event.timezone,month:'short'}).format(new Date(event.starts_at)).toUpperCase(),day:new Intl.DateTimeFormat('en-IN',{timeZone:event.timezone,day:'2-digit'}).format(new Date(event.starts_at))});
const slug=location.pathname.match(/^\/events\/([^/]+)\/?$/)?.[1];
const main=document.querySelector('main'),grid=document.querySelector('#event-grid'),city=document.querySelector('#city'),motion=document.querySelector('#motion-toggle'),legalFooter=document.querySelector('.site-footer')?.outerHTML||'';
const referralFromURL=new URLSearchParams(location.search).get('ref');
if(referralFromURL&&/^[A-Z0-9]{6,32}$/i.test(referralFromURL))localStorage.setItem('lucid-referral',referralFromURL.toUpperCase());
if(motion)motion.onclick=()=>{const paused=document.body.classList.toggle('motion-off');motion.setAttribute('aria-pressed',String(paused));motion.setAttribute('aria-label',paused?'Enable animations':'Pause animations');motion.querySelector('span').textContent=paused?'▷':'Ⅱ';};
function updateClock(){const clock=document.querySelector('#clock');if(clock)clock.textContent=new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'});}updateClock();setInterval(updateClock,60000);
if(slug){main.innerHTML='<section class="events-section" id="live-event"><p role="status">Loading event…</p></section>';for(const a of document.querySelectorAll('.menubar a,.dock a'))if(a.getAttribute('href')?.startsWith('#'))a.href='/'+a.getAttribute('href');}
else if(grid)grid.innerHTML='<p role="status">Loading upcoming events…</p>';
async function fetchJSON(url,options={}){const headers={...options.headers};if(options.body)headers['Content-Type']='application/json';const response=await fetch(url,{...options,headers});const data=await response.json();if(!response.ok)throw Error(data.error||'Unable to complete the request');return data;}
async function loadRazorpay(){if(window.Razorpay)return;await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://checkout.razorpay.com/v1/checkout.js';script.onload=resolve;script.onerror=()=>reject(Error('Payment window could not be loaded'));document.head.append(script);});}
function eventArtwork(event){const date=dateParts(event);return `<a class="event-card__visual" href="/events/${encodeURIComponent(event.slug)}/" aria-label="View ${escapeHTML(event.name)}">${event.image_url?`<img src="${escapeHTML(event.image_url)}" alt="" loading="lazy">`:'<span class="event-card__monogram" aria-hidden="true">L</span>'}<span class="event-card__shade"></span><span class="event-card__badge">${date.month}<strong>${date.day}</strong></span><span class="event-card__city">${escapeHTML(event.city)}</span></a>`;}
function renderCatalogue(){const selected=city?.value||'',visible=events.filter(event=>!selected||event.city===selected);grid.innerHTML=visible.length?visible.map(event=>{const date=dateParts(event);return `<article class="event-card">${eventArtwork(event)}<div class="event-card__body"><div class="event-card__host"><span class="event-card__hostmark">L</span><span>Hosted by <strong>Lucidsway</strong></span></div><h3><a href="/events/${encodeURIComponent(event.slug)}/">${escapeHTML(event.name)}</a></h3><p class="event-card__schedule">${escapeHTML(date.date)} · ${escapeHTML(date.time)}</p><p class="event-card__location">${escapeHTML(event.venue)} · ${escapeHTML(event.city)}</p><div class="event-card__footer"><span>${event.from_amount_paise!==null?'From '+money(event.from_amount_paise):'Details coming soon'}</span><a class="booking-link" href="/events/${encodeURIComponent(event.slug)}/">Get passes <span>↗</span></a></div></div></article>`;}).join(''):'<p role="status">New nights are on the way. Check back for upcoming events.</p>';}
if(slug){fetchJSON('/api/events/'+encodeURIComponent(slug)).then(({event:e})=>{const when=dateParts(e),referral=localStorage.getItem('lucid-referral')||'';document.title=e.name+' — The Lucid’s Way';document.body.classList.add('booking-page');document.querySelector('#live-event').outerHTML=`<div id="live-event" class="event-experience"><a class="event-back" href="/#events">← All events</a><section class="live-event-grid"><div class="event-detail-column"><article class="event-banner">${e.image_url?`<img src="${escapeHTML(e.image_url)}" alt="${escapeHTML(e.name)} event banner">`:'<span class="event-banner__monogram" aria-hidden="true">L</span>'}<div class="event-banner__top"><span>THE LUCID’S WAY</span><span>${escapeHTML(e.city.toUpperCase())}</span></div><div class="event-banner__bottom"><strong>${escapeHTML(e.name)}</strong><span>${escapeHTML(when.date)}</span></div></article><div class="event-title-block"><div class="event-date-tile"><span>${when.month}</span><strong>${when.day}</strong></div><div><span class="eyebrow">THE LUCID’S WAY PRESENTS</span><h1>${escapeHTML(e.name)}</h1><p>${escapeHTML(when.date)} · ${escapeHTML(when.time)}</p><p>${escapeHTML(e.venue)} · ${escapeHTML(e.city)} ${e.maps_url?`<a href="${escapeHTML(e.maps_url)}" target="_blank" rel="noopener">Map ↗</a>`:''}</p></div></div><section class="event-section"><span class="eyebrow">ABOUT THE NIGHT</span><p>${escapeHTML(e.description)}</p></section><section class="event-section event-policy"><span class="eyebrow">REFUND &amp; CANCELLATION TERMS</span><p>${escapeHTML(e.refund_policy)}</p><a href="/refunds/" target="_blank">Read the platform policy ↗</a></section><aside class="event-host"><span class="event-card__hostmark">L</span><div><small>HOSTED BY</small><strong>Lucidsway</strong><p>A brand operated by MegMultiMedia Pvt Ltd.</p></div></aside></div><form id="registration-form" class="event-booking-panel" novalidate><span class="eyebrow">GET PASSES</span><h2>Choose your entry.</h2><p class="panel-intro">Your ticket and one-time entry QR will live in your Lucidsway account.</p><div id="pass-choices">${e.passes.map((pass,index)=>`<label class="pass-choice"><input type="radio" name="pass" value="${pass.id}" data-amount="${pass.amount_paise}" ${index===0?'checked':''}><span class="pass-choice__check" aria-hidden="true"></span><span><strong>${escapeHTML(pass.name)}</strong><small>Digital entry pass</small></span><b>${money(pass.amount_paise)}</b></label>`).join('')}</div><label class="field-label">Quantity<select name="quantity">${Array.from({length:10},(_,index)=>`<option>${index+1}</option>`).join('')}</select></label><div class="code-fields"><label>Promo code<input name="coupon" maxlength="32" placeholder="Optional"></label><label>Referral code<input name="referral" maxlength="32" value="${escapeHTML(referral)}" placeholder="Optional"></label></div><div class="account-summary"><span class="account-summary__icon" aria-hidden="true">◉</span><div><strong id="account-name">Your Lucidsway account</strong><small id="account-contact">Sign in to continue</small></div><a href="/account" id="account-link">Sign in</a></div><div class="price-summary"><div><span>Pass subtotal</span><strong id="registration-subtotal"></strong></div><div id="discount-row" hidden><span>Discount</span><strong id="registration-discount"></strong></div><div class="price-summary__total"><span>Total</span><strong id="registration-total"></strong></div></div><details class="refund-terms"><summary>Refund &amp; cancellation terms</summary><p>${escapeHTML(e.refund_policy)}</p></details><label class="policy-consent"><input type="checkbox" name="policyConsent" required><span>I agree to this event’s refund and cancellation terms.</span></label><button class="button dark" type="submit"><span id="registration-action">Sign in to continue</span><span>↗</span></button><div class="secure-note"><span aria-hidden="true">⌁</span><span>${e.checkout_enabled?'Secure payment by Razorpay. Your pass is issued after payment verification.':'Online payment is being configured. No charge or ticket will be created yet.'}</span></div><p id="booking-status" role="status" aria-live="polite"></p></form></section>${legalFooter}</div>`;
 const form=document.querySelector('#registration-form'),subtotal=document.querySelector('#registration-subtotal'),discount=document.querySelector('#registration-discount'),discountRow=document.querySelector('#discount-row'),total=document.querySelector('#registration-total'),action=document.querySelector('#registration-action');let signedIn=false,checkoutKey=crypto.randomUUID();
 const updateTotal=()=>{const selected=form.querySelector('input[name="pass"]:checked'),amount=Number(selected.dataset.amount),quantity=Number(form.elements.quantity.value),value=amount*quantity;subtotal.textContent=money(value);total.textContent=money(value);discountRow.hidden=true;};form.addEventListener('change',updateTotal);updateTotal();
 fetch('/api/auth/me').then(async response=>{if(!response.ok)return;const {user}=await response.json();signedIn=true;document.querySelector('#account-name').textContent=user.name;document.querySelector('#account-contact').textContent=[user.email,user.phone].filter(Boolean).join(' · ');document.querySelector('#account-link').textContent='Account';action.textContent=e.checkout_enabled?'Continue to payment':'Reserve this pass';});
 form.onsubmit=async event=>{event.preventDefault();const status=document.querySelector('#booking-status');if(!signedIn){location.href='/account?return='+encodeURIComponent(location.pathname+location.search);return;}if(!form.reportValidity()){status.textContent='Please accept the event refund terms before continuing.';return;}const button=form.querySelector('button[type="submit"]');button.disabled=true;status.textContent='Confirming price and availability…';try{const data=await fetchJSON('/api/orders',{method:'POST',body:JSON.stringify({event_id:e.id,pass_id:form.elements.pass.value,quantity:Number(form.elements.quantity.value),referral_code:form.elements.referral.value.trim(),coupon_code:form.elements.coupon.value.trim(),idempotency_key:checkoutKey,accepted_refund_policy:form.elements.policyConsent.checked})});subtotal.textContent=money(data.order.subtotal_paise);discount.textContent='−'+money(data.order.discount_paise);discountRow.hidden=!data.order.discount_paise;total.textContent=money(data.order.amount_paise);status.textContent=`${data.order.reference}: ${data.message}`;await new Promise(requestAnimationFrame);if(data.payment){await loadRazorpay();new window.Razorpay({...data.payment,theme:{color:'#e21e35'},handler:async result=>{status.textContent='Verifying payment…';try{await fetchJSON('/api/payments/verify',{method:'POST',body:JSON.stringify(result)});checkoutKey=crypto.randomUUID();location.href='/account?view=tickets';}catch{status.textContent='Payment received. Your ticket will appear after capture is confirmed.';}}}).open();}}catch(error){status.textContent=error.message;}finally{button.disabled=false;}};
 }).catch(error=>{document.querySelector('#live-event').textContent=error.message;});
}else if(grid){fetchJSON('/api/events').then(data=>{events.push(...data.events);if(city){city.innerHTML='<option value="">All cities</option>'+[...new Set(events.map(event=>event.city))].sort().map(value=>`<option value="${escapeHTML(value)}">${escapeHTML(value)}</option>`).join('');city.onchange=renderCatalogue;}renderCatalogue();document.querySelector('.events-section .prototype-note')?.remove();}).catch(()=>{grid.innerHTML='<p role="alert">Events could not be loaded. Please refresh to try again.</p>';});}
